{"content":"import os
import re
from pathlib import Path

vault_dir = Path(r"D:\HERMES FILES\HERMES OBSIDIAN")
md_files = list(vault_dir.rglob("*.md"))

link_pattern = re.compile(r'\[\[([^\]|#]+)(?:#[^\]|]+)?(?:\|[^\]]+)?\]\]')

notes = {}
for p in md_files:
    rel = p.relative_to(vault_dir)
    stem = p.stem
    content = p.read_text(encoding="utf-8")
    links = link_pattern.findall(content)
    # clean links
    cleaned_links = [l.strip() for l in links]
    notes[stem] = {
        "rel_path": str(rel),
        "links": cleaned_links,
        "content_len": len(content),
        "title": p.name
    }

# Check resolution of links
all_stems = {p.stem: str(p.relative_to(vault_dir)) for p in md_files}

inbound = {stem: [] for stem in all_stems}
broken_links = []

for stem, data in notes.items():
    for target in data["links"]:
        # target might match stem or filename
        target_clean = Path(target).stem
        if target_clean in all_stems:
            inbound[target_clean].append(stem)
        else:
            broken_links.append((stem, target))

orphans_no_inbound = [s for s, inb in inbound.items() if len(inb) == 0 and s != "Главная"]
orphans_no_outbound = [s for s, d in notes.items() if len(d["links"]) == 0]
isolated = [s for s in orphans_no_inbound if s in orphans_no_outbound]

print(f"Total notes: {len(md_files)}")
print(f"Notes without inbound links ({len(orphans_no_inbound)}):")
for s in sorted(orphans_no_inbound):
    print(f"  - {s} ({all_stems[s]})")

print(f"\nNotes without outbound links ({len(orphans_no_outbound)}):")
for s in sorted(orphans_no_outbound):
    print(f"  - {s} ({all_stems[s]})")

print(f"\nIsolated notes (neither in nor out) ({len(isolated)}):")
for s in sorted(isolated):
    print(f"  - {s} ({all_stems[s]})")

print(f"\nBroken links ({len(broken_links)}):")
for src, tgt in broken_links:
    print(f"  {src} -> [[{tgt}]]")

print("\n--- Summary per directory ---")
dirs = {}
for p in md_files:
    d = str(p.parent.relative_to(vault_dir))
    dirs.setdefault(d, []).append(p.stem)
for d, flist in sorted(dirs.items()):
    print(f"{d} ({len(flist)} notes): {', '.join(flist[:5])}{'...' if len(flist)>5 else ''}")
